let currentUser=null,annualData=null,activeMonth=null,activeTab='partner',filterState='all',searchText='',cardSearchText='',editDirty=false;
const detailCache=new Map();
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');
const I={search:'<svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg>',edit:'<svg viewBox="0 0 24 24"><path d="M4 20h4l11-11-4-4L4 16z"/><path d="m13.5 6.5 4 4"/></svg>',trash:'<svg viewBox="0 0 24 24"><path d="M4 7h16M9 7V4h6v3M7 7l1 13h8l1-13"/></svg>',save:'<svg viewBox="0 0 24 24"><path d="M5 4h12l2 2v14H5z"/><path d="M8 4v6h8V4M8 20v-6h8v6"/></svg>',check:'<svg viewBox="0 0 24 24"><path d="m5 12 4 4L19 6"/></svg>',checkCircle:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/></svg>',x:'<svg viewBox="0 0 24 24"><path d="m7 7 10 10M17 7 7 17"/></svg>',plus:'<svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg>',download:'<svg viewBox="0 0 24 24"><path d="M12 3v12M7 10l5 5 5-5"/><path d="M5 20h14"/></svg>',arrow:'<svg viewBox="0 0 24 24"><path d="M5 12h13M13 7l5 5-5 5"/></svg>'};
const icon=n=>I[n]||'';
function goHome(){if(editDirty&&!confirm('저장하지 않은 변경사항이 있습니다. 이동할까요?'))return;location.href='/home'}
$('homeBtn').onclick=goHome;$('homeBrand').onclick=goHome;window.addEventListener('beforeunload',e=>{if(editDirty){e.preventDefault();e.returnValue=''}});
$('logoutBtn').onclick=()=>{editDirty=false;window.EHSAuth.logout()};
function showDetail(){ $('detailModal').classList.remove('hidden') }
function closeDetail(force=false){if(!force&&editDirty&&!confirm('수정사항을 닫을까요?'))return;editDirty=false;activeMonth=null;$('detailModal').classList.add('hidden');$('detail').innerHTML='<div class="detail-empty">월을 선택하세요.</div>';renderCards()}
$('detailClose').onclick=()=>closeDetail();$('detailModal').onclick=e=>{if(e.target===$('detailModal'))closeDetail()};
const api=(path,opt={})=>window.EHSApi.request(path,opt);
function buildYears(){const now=new Date().getFullYear();for(let y=now+1;y>=now-4;y--){const o=document.createElement('option');o.value=y;o.textContent=`${y}년`;if(y===now)o.selected=true;$('year').append(o)}$('year').onchange=()=>{if(editDirty&&!confirm('저장하지 않은 변경사항이 있습니다. 연도를 변경할까요?'))return;loadYear(true)}}
function monthOf(m){return Number(m?.meeting_month||String(m?.meeting_date||'').slice(5,7)||0)}function meetingByMonth(n){return (annualData?.meetings||[]).find(m=>monthOf(m)===n)||null}function pct(a,b){return b?Math.round(Number(a||0)/Number(b)*100):0}function dateText(v){return String(v||'').replaceAll('-','.')}
function latestMeeting(){return [...(annualData?.meetings||[])].sort((a,b)=>monthOf(b)-monthOf(a)||String(b.meeting_date||'').localeCompare(String(a.meeting_date||'')))[0]||null}
function summaryTone(absence){const n=Number(absence||0);return n===0?'tone-good':n===1?'tone-warn':'tone-bad'}
function renderLatest(){if(currentUser.role!=='admin'){const s=annualData?.summary||{},absence=Number(s.absence_count||0),tone=summaryTone(absence);$('latest').className='latest partner-summary';$('latest').innerHTML=`<div class="partner-summary-card"><span>협의체 점수</span><b><em class="${tone}" style="font-style:normal">${Number(s.score??10)}</em><span class="score-denom">/ 10점</span></b></div><div class="partner-summary-card"><span>불참 횟수</span><b class="${tone}">${absence}회</b></div>`;return}$('latest').className='latest';const m=latestMeeting();$('latest').innerHTML=m?`<span>대상 협력사 <b>${Number(m.partner_target_count||0)}개사</b></span><span>이루자 유관부서 <b>${Number(m.department_target_count||0)}개</b></span>`:'<span>대상 협력사 <b>0개사</b></span><span>이루자 유관부서 <b>0개</b></span>'}
function parseArrayMaybe(v){const s=String(v??'').trim();if(!s)return[];if(s.startsWith('[')){try{const a=JSON.parse(s);return Array.isArray(a)?a.map(x=>String(x??'').trim()).filter(Boolean):[s]}catch{}}return[s]}
function attendeesFromRow(r){const names=parseArrayMaybe(r?.attendee_name),positions=parseArrayMaybe(r?.attendee_position),out=[];for(let i=0;i<Math.max(names.length,positions.length);i++){const name=names[i]||'',position=positions[i]||'';if(name||position)out.push({name,position})}return out}
function packAttendees(list){const clean=(list||[]).map(x=>({name:String(x.name||'').trim(),position:String(x.position||'').trim()})).filter(x=>x.name||x.position);if(clean.length<=1)return{attendee_name:clean[0]?.name||null,attendee_position:clean[0]?.position||null};return{attendee_name:JSON.stringify(clean.map(x=>x.name)),attendee_position:JSON.stringify(clean.map(x=>x.position))}}
function detailStats(m,type){const rows=type==='partner'?(m?.partners||[]):(m?.departments||[]);return{target:rows.length,present:rows.filter(x=>x.attendance_status==='present').length,absent:rows.filter(x=>x.attendance_status==='absent').length}}
function ratesForCard(m){const p={target:Number(m.partner_target_count||0),present:Number(m.partner_present_count||0)};const d=detailCache.get(m.id);const ds=d?detailStats(d,'department'):{target:Number(m.department_target_count||0),present:null};return{p,d:ds}}
function annualRows(type){const key=type==='partner'?'company_id':'department_id',nameKey=type==='partner'?'company_name':'department_name',listKey=type==='partner'?'partners':'departments',map=new Map();for(const meeting of annualData?.meetings||[]){if(meeting.status!=='finalized')continue;const d=detailCache.get(meeting.id);if(!d)continue;const month=monthOf(meeting);for(const r of d[listKey]||[]){if(!map.has(r[key]))map.set(r[key],{id:r[key],name:r[nameKey]||r[key],months:{}});map.get(r[key]).months[month]={status:r.attendance_status,finalized:true}}}return [...map.values()].sort((a,b)=>String(a.name).localeCompare(String(b.name),'ko'))}
function stampHtml(row,month){const v=row.months[month],meeting=meetingByMonth(month);if(meeting&&meeting.status!=='finalized')return '<span class="stamp none">-</span>';if(!v||v.status==='pending')return '<span class="stamp none">-</span>';if(v.status==='present')return `<span class="stamp present" title="${month}월 참석">O</span>`;return `<span class="stamp absent" title="${month}월 불참">X</span>`}
function absenceHtml(row){const n=Object.values(row.months).filter(x=>x.finalized&&x.status==='absent').length,cls=n===0?'zero':n===1?'one':'many';return `<div class="absence-count ${cls}" title="완료 회차만 반영">${n===0?'-':n+'회'}</div>`}
function annualSection(type,title){const rows=annualRows(type),head=`<div class="att-head"><span>소속</span>${Array.from({length:12},(_,i)=>`<span class="months-label">${i+1}월</span>`).join('')}<span class="absence-head">불참 횟수</span></div>`,body=rows.length?rows.map(r=>`<div class="att-row"><div class="att-org">${esc(r.name)}</div>${Array.from({length:12},(_,i)=>stampHtml(r,i+1)).join('')}${absenceHtml(r)}</div>`).join(''):'<div class="annual-empty">완료된 참석현황이 없습니다.</div>';return `<section class="annual-card"><div class="annual-head"><strong>${title}</strong></div><div class="attendance-grid">${head}${body}</div></section>`}
function renderAnnualAttendance(){if(currentUser?.role!=='admin'){$('annualAttendance').classList.add('hidden');return}$('annualAttendance').classList.remove('hidden');const meetings=annualData?.meetings||[],ready=meetings.every(m=>detailCache.has(m.id));if(!ready){$('annualBody').innerHTML='<div class="annual-card"><div class="annual-loading">불러오는 중...</div></div>';return}$('annualBody').innerHTML=`<div class="annual-wrap">${annualSection('partner','협력사')}${annualSection('department','이루자 유관부서')}</div>`}
function adminCard(m,n){const r=ratesForCard(m),done=m.status==='finalized',absent=Number(m.partner_absent_count||0),dept=r.d.present==null?'–':`${r.d.present}/${r.d.target}`;return `<button class="month-card ${done?'done':'edit'} ${activeMonth===n?'active':''}" data-month="${n}" type="button"><div class="month-top"><span class="month-no">${n}월</span><strong class="meeting-date">${esc(dateText(m.meeting_date))}</strong></div><div class="month-main">협력사 참석 ${r.p.present}/${r.p.target}</div><div class="month-sub">불참 ${absent} · 유관부서 ${dept}</div><div class="month-result ${done?'done':'edit'}">${done?'완료':'수정'}</div></button>`}
function partnerCard(m,n){const present=m.attendance_status==='present',a=attendeesFromRow(m),body=present?`<div class="month-people">${a.map(x=>`<span class="month-person">${esc(`${x.position||''} ${x.name||''}`.trim()||'-')}</span>`).join('')}</div>`:'<div class="partner-absent-label">불참</div>';return `<article class="month-card partner-static ${present?'done':'absent'}"><div class="month-top"><span class="month-no">${n}월</span><strong class="meeting-date">${esc(dateText(m.meeting_date))}</strong></div>${body}</article>`}
function emptyCard(n){if(currentUser.role!=='admin')return `<article class="month-card partner-static"><div class="month-top"><span class="month-no">${n}월</span></div></article>`;return `<button class="month-card ${activeMonth===n?'active':''}" data-month="${n}" type="button"><div class="month-top"><span class="month-no">${n}월</span><strong class="meeting-date">미등록</strong></div><div class="empty-card">눌러서 등록</div></button>`}
function bindCards(){if(currentUser.role!=='admin')return;$('months').querySelectorAll('button.month-card').forEach(b=>b.onclick=()=>openMonth(Number(b.dataset.month)))}
function meetingSearchText(m){if(!m)return'';const base=[m.title,m.meeting_date,m.attendee_position,m.attendee_name];if(currentUser.role==='admin'){const d=detailCache.get(m.id);for(const r of [...(d?.partners||[]),...(d?.departments||[])]){base.push(r.company_name,r.department_name,r.attendee_position,r.attendee_name)}}return base.join(' ').toLowerCase()}
function renderCards(){const q=cardSearchText.trim().toLowerCase(),cards=Array.from({length:12},(_,i)=>i+1).filter(n=>{if(!q)return true;const m=meetingByMonth(n);return !!m&&meetingSearchText(m).includes(q)}).map(n=>{const m=meetingByMonth(n);if(!m)return emptyCard(n);return currentUser.role==='admin'?adminCard(m,n):partnerCard(m,n)});$('months').innerHTML=cards.length?cards.join(''):'<div class="annual-empty" style="grid-column:1/-1">검색 결과가 없습니다.</div>';bindCards()}
async function hydrateDetails(){if(currentUser.role!=='admin')return;const list=(annualData?.meetings||[]).filter(m=>!detailCache.has(m.id));let idx=0;const worker=async()=>{while(idx<list.length){const m=list[idx++];try{const d=(await api(`/api/admin/committee/${encodeURIComponent(m.id)}`)).meeting;detailCache.set(m.id,d)}catch{}}};await Promise.all(Array.from({length:Math.min(4,list.length)},()=>worker()));renderCards();renderAnnualAttendance();if(activeMonth){const m=meetingByMonth(activeMonth),d=m&&detailCache.get(m.id);if(d)renderAdminDetail(d)}}
async function loadYear(force=false){activeMonth=null;editDirty=false;if(force)detailCache.clear();$('detailModal').classList.add('hidden');$('months').innerHTML='<div class="loading" style="grid-column:1/-1">불러오는 중...</div>';try{annualData=await api(`/api/committee?year=${encodeURIComponent($('year').value)}`);renderLatest();renderCards();renderAnnualAttendance();void hydrateDetails()}catch(e){$('months').innerHTML=`<div class="error" style="grid-column:1/-1">${esc(e.message)}</div>`}}
$('refreshBtn').onclick=()=>{if(editDirty&&!confirm('저장하지 않은 변경사항이 있습니다. 새로고침할까요?'))return;loadYear(true)};
$('attendanceSearch').oninput=e=>{cardSearchText=e.target.value;renderCards()};
async function openMonth(n){if(editDirty&&n!==activeMonth&&!confirm('저장하지 않은 변경사항이 있습니다. 다른 월로 이동할까요?'))return;activeMonth=n;editDirty=false;activeTab='partner';filterState='all';searchText='';renderCards();showDetail();const m=meetingByMonth(n);if(!m){currentUser.role==='admin'?renderCreate(n):$('detail').innerHTML='<div class="detail-empty">대상 회차가 없습니다.</div>';return}if(currentUser.role==='partner'){renderPartnerDetail(m);return}let d=detailCache.get(m.id);if(!d){$('detail').innerHTML='<div class="loading">불러오는 중...</div>';try{d=(await api(`/api/admin/committee/${encodeURIComponent(m.id)}`)).meeting;detailCache.set(m.id,d);renderCards();renderAnnualAttendance()}catch(e){$('detail').innerHTML=`<div class="error">${esc(e.message)}</div>`;return}}renderAdminDetail(d)}
function renderPartnerDetail(m){const a=attendeesFromRow(m),present=m.attendance_status==='present';$('detail').innerHTML=`<div class="detail-head"><div class="detail-title"><strong>${monthOf(m)}월 협의체 참석현황</strong><span>${esc(dateText(m.meeting_date))} · 완료</span></div></div><div class="detail-body"><div class="kpis" style="padding:0"><div class="kpi ${present?'present':'absent'}"><span>참석 결과</span><b>${present?'참석':'불참'}</b></div><div class="kpi"><span>참석자</span><b style="font-size:13px">${a.length}명</b></div></div>${a.length?`<section class="people-card" style="margin-top:10px"><div class="people-card-head"><strong>참석자</strong></div><div class="people">${a.map(x=>`<div class="person-row" style="grid-template-columns:1fr 1fr"><div class="org">${esc(x.position||'-')}</div><div class="attendee-one">${esc(x.name||'-')}</div></div>`).join('')}</div></section>`:''}<div class="actions"><span class="grow"></span><button class="action-text primary" type="button" onclick="closeDetail(true)">완료</button></div></div>`}
function renderCreate(n){const y=Number($('year').value),mm=String(n).padStart(2,'0');$('detail').innerHTML=`<div class="detail-head"><div class="detail-title"><strong>${n}월 협의체 등록</strong><span>입력 후 참석현황을 완료하세요.</span></div></div><div class="edit"><div class="fields"><div class="field"><label>실시일</label><input id="createDate" type="date" value="${y}-${mm}-01"></div><div class="field"><label>비고</label><textarea id="createNote"></textarea></div></div><div class="actions"><span class="grow"></span><button class="action-text" type="button" onclick="closeDetail()">닫기</button><button class="action-text primary" id="createBtn" type="button">생성</button></div></div>`;$('createBtn').onclick=()=>createMeeting(n)}
async function createMeeting(n){const b=$('createBtn');b.disabled=true;try{const d=await api('/api/admin/committee',{method:'POST',body:JSON.stringify({year:Number($('year').value),month:n,meeting_date:$('createDate').value,note:$('createNote').value.trim()})});detailCache.set(d.meeting.id,d.meeting);updateLocal(d.meeting);renderLatest();renderCards();renderAnnualAttendance();renderEdit(d.meeting)}catch(e){alert(e.message);b.disabled=false}}
function filteredRows(m){let rows=activeTab==='partner'?(m.partners||[]):(m.departments||[]);if(filterState!=='all')rows=rows.filter(x=>x.attendance_status===filterState);const q=searchText.trim().toLowerCase();if(q)rows=rows.filter(r=>{const people=attendeesFromRow(r).map(x=>`${x.position} ${x.name}`).join(' ');return `${activeTab==='partner'?r.company_name:r.department_name} ${people}`.toLowerCase().includes(q)});return rows}
function peopleHtml(rows,type){if(!rows.length)return'<div class="list-empty">표시할 항목이 없습니다.</div>';return rows.map(r=>{const org=type==='partner'?r.company_name:r.department_name,a=attendeesFromRow(r);const people=a.length?a.map(x=>`<div class="attendee-one">${esc(`${x.position||''} ${x.name||''}`.trim())}</div>`).join(''):'<div class="attendee-one">-</div>';return `<div class="person-row view-row"><div class="org">${esc(org)}</div><span class="state ${esc(r.attendance_status)}">${r.attendance_status==='present'?'O':r.attendance_status==='absent'?'X':'-'}</span><div class="attendees-view">${people}</div></div>`}).join('')}
function renderPeople(m){$('people').innerHTML=peopleHtml(filteredRows(m),activeTab);$('detail').querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===activeTab));$('detail').querySelectorAll('.filter').forEach(f=>f.classList.toggle('active',f.dataset.filter===filterState));$('detail').querySelectorAll('.add-person').forEach(b=>b.onclick=()=>renderEdit(m,b.dataset.id,true))}
function exportExcel(m){const rows=[];for(const [type,list] of [['협력사',m.partners||[]],['이루자 유관부서',m.departments||[]]])for(const r of list){const org=type==='협력사'?r.company_name:r.department_name,a=attendeesFromRow(r);if(a.length){a.forEach(x=>rows.push([type,org,r.attendance_status==='present'?'참석':r.attendance_status==='absent'?'불참':'미정',x.position||'',x.name||'']))}else rows.push([type,org,r.attendance_status==='present'?'참석':r.attendance_status==='absent'?'불참':'미정','',''])}const cells=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');const table=`<table border="1"><tr><th>구분</th><th>회사/부서</th><th>참석여부</th><th>직급</th><th>성명</th></tr>${rows.map(r=>`<tr>${r.map(c=>`<td>${cells(c)}</td>`).join('')}</tr>`).join('')}</table>`;const html=`<html><head><meta charset="utf-8"></head><body><h3>${$('year').value}년 ${monthOf(m)}월 안전보건협의체 참석자명단</h3>${table}</body></html>`;const blob=new Blob(['\ufeff',html],{type:'application/vnd.ms-excel;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${$('year').value}년_${monthOf(m)}월_안전보건협의체_참석자명단.xls`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function renderAdminDetail(m){const s=detailStats(m,'partner'),d=detailStats(m,'department'),columns='<div class="people-columns"><span>소속</span><span>참석</span><span>직급 / 성명</span></div>';$('detail').innerHTML=`<div class="detail-head"><div class="detail-head-row"><div class="detail-title"><strong>${monthOf(m)}월 협의체 참석현황</strong><span>${esc(dateText(m.meeting_date))}</span></div><div class="detail-actions"><button class="icon" id="excelBtn" data-tip="Excel 추출" aria-label="Excel 추출">${icon('download')}</button><button class="action-text" id="editBtn" type="button">수정</button></div></div></div><div class="kpis"><div class="kpi"><span>협력사 대상</span><b>${s.target}</b></div><div class="kpi present"><span>참석</span><b>${s.present}</b></div><div class="kpi absent"><span>불참</span><b>${s.absent}</b></div></div><div class="detail-body"><div class="detail-columns"><section class="people-card"><div class="people-card-head"><strong>협력사</strong><span class="count">${s.present}/${s.target} 참석</span></div>${columns}<div class="people">${peopleHtml(m.partners||[],'partner')}</div></section><section class="people-card"><div class="people-card-head"><strong>이루자 유관부서</strong><span class="count">${d.present}/${d.target} 참석</span></div>${columns}<div class="people">${peopleHtml(m.departments||[],'department')}</div></section></div>${m.note?`<div class="note">${esc(m.note)}</div>`:''}</div>`;$('excelBtn').onclick=()=>exportExcel(m);$('editBtn').onclick=()=>renderEdit(m)}
function statusOptions(v){return [['pending','미정'],['present','참석'],['absent','불참'],['excluded','비대상']].map(([x,t])=>`<option value="${x}" ${x===v?'selected':''}>${t}</option>`).join('')}
function attendeeEditorHtml(r){let a=attendeesFromRow(r);if(!a.length)a=[{position:'',name:''}];return `<div class="attendee-editor">${a.map((x,i)=>`<div class="attendee-edit-row"><input class="position" placeholder="직급" value="${esc(x.position)}"><input class="name" placeholder="성명" value="${esc(x.name)}"><button class="remove-person" type="button" ${i===0?'style="visibility:hidden"':''}>×</button></div>`).join('')}</div>`}
function targetRows(options,selected,type){const key=type==='partner'?'company_id':'department_id',nameKey=type==='partner'?'company_name':'department_name',map=new Map((selected||[]).map(r=>[r[key],r]));return (options||[]).map(o=>{const existing=map.get(o.id),r=existing||{[key]:o.id,attendance_status:'excluded',attendee_name:null,attendee_position:null},targeted=!!existing;return `<div class="target ${r.attendance_status==='present'?'':'attendance-locked'}" data-id="${esc(o.id)}" data-original-target="${targeted?'1':'0'}" data-search="${esc(String(o[nameKey]||'').toLowerCase())}"><div class="target-main"><span>${esc(o[nameKey])}</span></div><select class="status-sel">${statusOptions(r.attendance_status)}</select><div>${attendeeEditorHtml(r)}</div><button class="row-add" type="button" data-tip="참석자 추가" aria-label="참석자 추가">${icon('plus')}</button></div>`}).join('')}
function addAttendeeInput(target){const ed=target.querySelector('.attendee-editor'),row=document.createElement('div');row.className='attendee-edit-row';row.innerHTML='<input class="position" placeholder="직급"><input class="name" placeholder="성명"><button class="remove-person" type="button">×</button>';ed.append(row);bindPersonRow(row);markDirty();row.querySelector('.position').focus()}
function bindPersonRow(row){row.querySelectorAll('input').forEach(i=>i.oninput=markDirty);const rm=row.querySelector('.remove-person');if(rm)rm.onclick=()=>{row.remove();markDirty()}}
function markDirty(){editDirty=true;const s=$('dirtyState');if(s)s.textContent='수정됨'}
function updateCount(type){const id=type==='partner'?'partnerRows':'departmentRows',c=type==='partner'?'partnerCount':'departmentCount';$(c).textContent=`대상 ${[...$(id).querySelectorAll('.status-sel')].filter(x=>x.value!=='excluded').length}`}
function syncTargetAttendanceState(t,clear=false){const s=t.querySelector('.status-sel'),locked=s.value==='absent'||s.value==='excluded';t.classList.toggle('attendance-locked',locked);t.querySelectorAll('.attendee-edit-row input,.remove-person').forEach(el=>el.disabled=locked);t.querySelector('.row-add').disabled=locked;if(locked&&clear){const ed=t.querySelector('.attendee-editor'),first=ed.querySelector('.attendee-edit-row');ed.querySelectorAll('.attendee-edit-row').forEach((r,i)=>{if(i)r.remove()});first?.querySelectorAll('input').forEach(i=>i.value='')}}
function bindTargets(id,type){$(id).querySelectorAll('.target').forEach(t=>{const s=t.querySelector('.status-sel');s.onchange=()=>{syncTargetAttendanceState(t,true);updateCount(type);markDirty()};t.querySelectorAll('.attendee-edit-row').forEach(bindPersonRow);t.querySelector('.row-add')?.addEventListener('click',()=>addAttendeeInput(t));syncTargetAttendanceState(t)})}
function filterTargets(id,q){const v=String(q||'').trim().toLowerCase();$(id).querySelectorAll('.target').forEach(t=>t.classList.toggle('hide',v&&!t.dataset.search.includes(v)))}
function setAllPresent(id,type){$(id).querySelectorAll('.target').forEach(t=>{const s=t.querySelector('.status-sel');if(s.value==='excluded')return;s.value='present';syncTargetAttendanceState(t)});updateCount(type);markDirty()}
function fillPreviousRows(id,rows,key){const map=new Map((rows||[]).map(r=>[String(r[key]),r]));$(id).querySelectorAll('.target').forEach(t=>{const r=map.get(String(t.dataset.id)),a=attendeesFromRow(r);if(!r||!a.length)return;const ed=t.querySelector('.attendee-editor');ed.innerHTML=a.map((x,i)=>`<div class="attendee-edit-row"><input class="position" placeholder="직급" value="${esc(x.position)}"><input class="name" placeholder="성명" value="${esc(x.name)}"><button class="remove-person" type="button" ${i===0?'style="visibility:hidden"':''}>×</button></div>`).join('');ed.querySelectorAll('.attendee-edit-row').forEach(bindPersonRow);t.querySelector('.status-sel').value='present';syncTargetAttendanceState(t)});markDirty()}
async function loadPreviousAttendees(m){const b=$('previousBtn');b.disabled=true;b.textContent='불러오는 중...';try{const d=await api(`/api/admin/committee/${encodeURIComponent(m.id)}/previous-attendees`);if(!d.previous_meeting){b.textContent='전월 참석자 불러오기';alert('불러올 전월 참석자가 없습니다.');return}fillPreviousRows('partnerRows',d.partners,'company_id');fillPreviousRows('departmentRows',d.departments,'department_id');updateCount('partner');updateCount('department');b.textContent=`${Number(d.previous_meeting.meeting_month)}월 참석자 불러옴`}catch(e){alert(e.message);b.textContent='전월 참석자 불러오기'}finally{b.disabled=false}}
function renderEdit(m){editDirty=false;$('detail').innerHTML=`<div class="detail-head"><div class="detail-head-row"><div class="detail-title"><strong>${monthOf(m)}월 협의체 수정</strong><span>${esc(dateText(m.meeting_date))} · 입력 후 완료하세요.</span></div><button class="action-text" id="previousBtn" type="button">전월 참석자 불러오기</button></div></div><div class="edit"><div class="fields"><div class="field"><label>실시일</label><input id="meetingDate" type="date" value="${esc(m.meeting_date||'')}"></div><div class="field"><label>비고</label><textarea id="meetingNote">${esc(m.note||'')}</textarea></div></div><div class="edit-grid"><section class="edit-section"><div class="edit-section-head"><strong>협력사</strong><div class="edit-tools"><span class="count" id="partnerCount"></span><button class="mini" id="allPresentPartner" data-tip="대상 전체 참석">${icon('check')}</button></div></div><div class="search edit-search">${icon('search')}<input id="partnerSearch" placeholder="협력사 검색"></div><div class="targets" id="partnerRows">${targetRows(annualData.options?.companies,m.partners,'partner')}</div></section><section class="edit-section"><div class="edit-section-head"><strong>이루자 유관부서</strong><div class="edit-tools"><span class="count" id="departmentCount"></span><button class="mini" id="allPresentDepartment" data-tip="대상 전체 참석">${icon('check')}</button></div></div><div class="search edit-search">${icon('search')}<input id="departmentSearch" placeholder="유관부서 검색"></div><div class="targets" id="departmentRows">${targetRows(annualData.options?.departments,m.departments,'department')}</div></section></div><div class="actions"><button class="action-text danger" id="deleteBtn" type="button">삭제</button><span class="dirty" id="dirtyState"></span><span class="save-state" id="saveState"></span><span class="grow"></span><button class="action-text" id="cancelBtn" type="button">닫기</button><button class="action-text primary" id="saveBtn" type="button">완료</button></div></div>`;bindTargets('partnerRows','partner');bindTargets('departmentRows','department');updateCount('partner');updateCount('department');$('meetingDate').onchange=markDirty;$('meetingNote').oninput=markDirty;$('partnerSearch').oninput=e=>filterTargets('partnerRows',e.target.value);$('departmentSearch').oninput=e=>filterTargets('departmentRows',e.target.value);$('allPresentPartner').onclick=()=>setAllPresent('partnerRows','partner');$('allPresentDepartment').onclick=()=>setAllPresent('departmentRows','department');$('previousBtn').onclick=()=>loadPreviousAttendees(m);$('cancelBtn').onclick=()=>{if(editDirty&&!confirm('수정사항을 취소할까요?'))return;editDirty=false;renderAdminDetail(m)};$('deleteBtn').onclick=()=>deleteMeeting(m);$('saveBtn').onclick=()=>saveMeeting(m)}
function collect(id,key){const rows=[],preference_changes=[];for(const t of $(id).querySelectorAll('.target')){const status=t.querySelector('.status-sel').value,targeted=status!=='excluded',wasTarget=t.dataset.originalTarget==='1';if(targeted!==wasTarget)preference_changes.push({entity_id:t.dataset.id,is_target:targeted});if(!targeted)continue;const attendees=[...t.querySelectorAll('.attendee-edit-row')].map(r=>({position:r.querySelector('.position').value.trim(),name:r.querySelector('.name').value.trim()})).filter(x=>x.position||x.name),packed=packAttendees(attendees);rows.push({[key]:t.dataset.id,attendance_status:status,...packed,attendees})}return{rows,preference_changes}}
function validate(rows,label){for(const r of rows){if(r.attendance_status==='pending')return`${label} 참석여부를 모두 지정하세요.`;if(r.attendance_status==='present'){if(!r.attendees.length)return`참석 ${label}의 참석자를 입력하세요.`;if(r.attendees.some(a=>!a.position||!a.name))return`참석 ${label}의 직급과 성명을 모두 입력하세요.`}}return null}
function updateLocal(d){const i=annualData.meetings.findIndex(x=>x.id===d.id),p=d.partners||[];const x={...d,partner_target_count:p.length,partner_present_count:p.filter(r=>r.attendance_status==='present').length,partner_absent_count:p.filter(r=>r.attendance_status==='absent').length,partner_pending_count:p.filter(r=>r.attendance_status==='pending').length,department_target_count:(d.departments||[]).length};if(i>=0)annualData.meetings[i]={...annualData.meetings[i],...x};else annualData.meetings.push(x)}
async function saveMeeting(m){const p=collect('partnerRows','company_id'),d=collect('departmentRows','department_id'),msg=validate(p.rows,'협력사')||validate(d.rows,'이루자 유관부서');if(msg){alert(msg);return}$('saveState').textContent='완료 중...';try{const body={meeting_date:$('meetingDate').value,note:$('meetingNote').value.trim(),partners:p.rows.map(({attendees,...x})=>x),departments:d.rows.map(({attendees,...x})=>x),preference_changes:{partners:p.preference_changes,departments:d.preference_changes},finalize:true,expected_updated_at:m.updated_at};if(m.status==='finalized')body.reopen=true;const res=await api(`/api/admin/committee/${encodeURIComponent(m.id)}`,{method:'PATCH',body:JSON.stringify(body)});editDirty=false;detailCache.set(m.id,res.meeting);updateLocal(res.meeting);renderLatest();renderCards();renderAnnualAttendance();renderAdminDetail(res.meeting)}catch(e){alert(e.message);renderEdit(m)}}
async function deleteMeeting(m){if(!confirm(`${monthOf(m)}월 협의체를 삭제할까요?`))return;try{await api(`/api/admin/committee/${encodeURIComponent(m.id)}?force=1`,{method:'DELETE'});editDirty=false;annualData.meetings=annualData.meetings.filter(x=>x.id!==m.id);detailCache.delete(m.id);activeMonth=null;renderLatest();renderCards();renderAnnualAttendance();closeDetail(true)}catch(e){alert(e.message)}}
(async()=>{try{currentUser=await window.EHSAuth.requireUser();const admin=currentUser.role==='admin';$('pageTitle').textContent=admin?'협의체 참석관리':'협의체 참석현황';$('roleChip').classList.add('hidden');buildYears();$('userLabel').textContent=[currentUser.position,currentUser.name].filter(Boolean).join(' ')||currentUser.email||'';await loadYear()}catch(e){if(e?.status===401)return;const msg=window.EHSApi.describe(e);$('months').innerHTML=`<div class="error" style="grid-column:1/-1">${esc(msg)}</div>`;$('detail').innerHTML=`<div class="error">${esc(msg)}</div>`}})();
